\centering
\small
\begin{tabular}{@{}llrrr@{}}
\toprule
\textbf{Model} & \textbf{Setting} & \textbf{Unconstr.} & \textbf{Trie-only} & \textbf{Full S1} \\
& & \textbf{DR\,(\%)} & \textbf{DR\,(\%)} & \textbf{DR\,(\%)} \\
